    out = {"message_id": obj["message_id"], "turn_id": obj["turn_id"], "message": obj["message"]}
    if "turn_config" in obj and obj["turn_config"] is not None:
        out["turn_config"] = obj["turn_config"]
    if "history_artifact" in obj and obj["history_artifact"] is not None:
        out["history_artifact"] = obj["history_artifact"]
    return out

def revision(records):
    # mirrors uy(): sha256 over "[" + canon,canon,... + "]"
    h = hashlib.sha256()
    h.update(b"[")
    for i, r in enumerate(records):
        if i:
            h.update(b",")
        h.update(canon(normalize(r)).encode("utf-8"))
    h.update(b"]")
    return "sha256:" + h.hexdigest()

def load(path):
    return [json.loads(l) for l in open(path, encoding="utf-8") if l.strip()]

if __name__ == "__main__":
    print(revision(load(sys.argv[1])))
